INSERT INTO `ep_topic_packs` VALUES (24954,64,6,'Hindi','hi','सैर','[\"सैर का मतलब है किसी जगह की यात्रा करना।\",\"सैर में हम प्रकृति, ऐतिहासिक स्थल, या किसी विशेष जगह को देख सकते हैं।\",\"सैर के दौरान हम यात्रा के साधन चुनते हैं: जल, थल, वायु।\",\"जल मार्ग से यात्रा करने के लिये नाव, जहाज आदि उपयोग होते हैं।\",\"थल मार्ग से यात्रा करने के लिये गाड़ी, साइकिल, पैदल चलना आदि।\",\"वायु मार्ग से यात्रा करने के लिये हवाई जहाज, हेलीकॉप्टर आदि।\",\"सैर के दौरान हमें आसपास के लोगों से बातचीत करनी चाहिए।\",\"व्यवसायियों से बात करके उनके सुख-दुख को समझना सीखते हैं।\",\"सैर के दौरान चित्रों को देखकर उनके बारे में प्रश्न पूछना अच्छा होता है।\",\"सैर के दौरान अपने अनुभव को लिखना या बोलना यादगार रहता है।\",\"सैर के दौरान पर्यावरण का ध्यान रखना ज़रूरी है।\",\"सैर के दौरान सुरक्षित रहना और नियमों का पालन करना चाहिए।\",\"सैर के दौरान नई जगहों के नाम और इतिहास सीखना मज़ेदार होता है।\",\"सैर के दौरान मौसम और समय का ध्यान रखना चाहिए।\",\"सैर के दौरान अपनी यात्रा की योजना बनाना अच्छा होता है।\",\"सैर के दौरान दोस्तों या परिवार के साथ जाना मज़ा बढ़ाता है।\",\"सैर के दौरान तस्वीरें खींचना यादें संजोने में मदद करता है।\",\"सैर के दौरान स्थानीय व्यंजन चखना भी अनुभव का हिस्सा है।\",\"सैर के दौरान स्थानीय भाषा या बोलियों को सुनना सीखने का मौका देता है।\",\"सैर के दौरान अपने अनुभव को दूसरों के साथ साझा करना अच्छा होता है।\",\"सैर के दौरान प्रकृति के प्रति सम्मान दिखाना ज़रूरी है।\",\"सैर के दौरान अपनी यात्रा का एक छोटा डायरी रखना अच्छा अभ्यास है।\",\"सैर के दौरान यात्रा के दौरान आने वाली समस्याओं का समाधान ढूंढना सीखते हैं।\",\"सैर के दौरान अपने अनुभव को कहानी के रूप में सुनाना मज़ेदार होता है।\",\"सैर के दौरान यात्रा के दौरान मिलने वाली नई चीज़ों को नोट करना अच्छा होता है।\"]','[{\"q\":\"सैर का मुख्य उद्देश्य क्या है?\",\"options\":[\"किसी जगह पर जाना\",\"किसी से बात करना\",\"किसी को दिखाना\",\"किसी को सुनना\"],\"answer\":0,\"explain\":\"सैर का मुख्य उद्देश्य किसी जगह पर जाना और अनुभव करना है।\"},{\"q\":\"सैर के दौरान कौन सा साधन जल मार्ग से यात्रा के लिये इस्तेमाल होता है?\",\"options\":[\"साइकिल\",\"नाव\",\"हेलीकॉप्टर\",\"पैदल\"],\"answer\":1,\"explain\":\"नाव जल मार्ग से यात्रा के लिये इस्तेमाल होती है।\"},{\"q\":\"सैर के दौरान थल मार्ग से यात्रा के लिये कौन सा साधन उपयोगी है?\",\"options\":[\"हवाई जहाज\",\"नाव\",\"साइकिल\",\"हेलीकॉप्टर\"],\"answer\":2,\"explain\":\"साइकिल थल मार्ग से यात्रा के लिये उपयोगी है।\"},{\"q\":\"सैर के दौरान वायु मार्ग से यात्रा के लिये कौन सा साधन इस्तेमाल होता है?\",\"options\":[\"नाव\",\"साइकिल\",\"हेलीकॉप्टर\",\"पैदल\"],\"answer\":2,\"explain\":\"हेलीकॉप्टर वायु मार्ग से यात्रा के लिये इस्तेमाल होता है।\"},{\"q\":\"सैर के दौरान स्थानीय व्यवसायियों से बात करके क्या सीखते हैं?\",\"options\":[\"उनकी भाषा\",\"उनके सुख-दुख\",\"उनकी गाड़ी\",\"उनकी तस्वीरें\"],\"answer\":1,\"explain\":\"व्यवसायियों से बात करके उनके सुख-दुख को समझते हैं।\"},{\"q\":\"सैर के दौरान चित्रों को देखकर क्या करना चाहिए?\",\"options\":[\"उन्हें फेंकना\",\"उन्हें देखना और प्रश्न पूछना\",\"उन्हें खींचना\",\"उन्हें लिखना\"],\"answer\":1,\"explain\":\"चित्रों को देखकर उनके बारे में प्रश्न पूछना चाहिए।\"},{\"q\":\"सैर के दौरान अनुभव को किस रूप में याद रखना अच्छा है?\",\"options\":[\"कविता\",\"कहानी\",\"संगीत\",\"डायरी\"],\"answer\":3,\"explain\":\"डायरी में अनुभव को लिखना याद रखने में मदद करता है।\"},{\"q\":\"सैर के दौरान मौसम का ध्यान क्यों रखना चाहिए?\",\"options\":[\"क्योंकि मौसम बदलता है\",\"क्योंकि मौसम अच्छा है\",\"क्योंकि मौसम नहीं बदलता\",\"क्योंकि मौसम नहीं है\"],\"answer\":0,\"explain\":\"मौसम बदलता रहता है, इसलिए ध्यान रखना ज़रूरी है।\"},{\"q\":\"सैर के दौरान पर्यावरण का ध्यान रखना क्यों ज़रूरी है?\",\"options\":[\"क्योंकि यह मज़ा देता है\",\"क्योंकि यह सुंदर है\",\"क्योंकि यह ज़रूरी है\",\"क्योंकि यह आसान है\"],\"answer\":2,\"explain\":\"पर्यावरण का ध्यान रखना ज़रूरी है।\"},{\"q\":\"सैर के दौरान अपनी यात्रा की योजना बनाने का क्या लाभ है?\",\"options\":[\"समय बचता है\",\"पैसा बचता है\",\"दोस्त मिलते हैं\",\"सभी सही\"],\"answer\":3,\"explain\":\"योजना बनाने से समय, पैसा और दोस्ती दोनों लाभ होते हैं।\"}]','nvidia/openai/gpt-oss-20b','2026-10-17 16:34:55'),(24955,64,6,'Hindi','hi','बसंती हवा','[\"बसंती हवा का परिचय – यह एक कविता है जो वसंत ऋतु की हल्की, खुशमिजाज हवा के बारे में बताती है।\",\"कविता में हवा को ‘बसंती हवा’ कहा गया है, जिसका अर्थ है वसंत की हवा।\",\"हवा को अक्सर ‘हवा हूँ, हवा मैं’ के रूप में व्यक्त किया जाता है, जिससे उसकी स्वतंत्रता और हलचल दिखती है।\",\"कविता में हवा को ‘बावली’, ‘मस्तमौला’, ‘बड़ी बावली’ आदि शब्दों से वर्णित किया गया है, जो उसकी चंचलता और ऊर्जा को दर्शाते हैं।\",\"हवा के गुण – तेज़, हल्की, चलती-फिरती, बिना किसी सीमा के चलने वाली।\",\"हवा का महत्व – पौधों के परागण में मदद करती है, मौसम को संतुलित रखती है, और हमें ताज़गी देती है।\",\"हवा के बिना प्रकृति – पौधों की वृद्धि धीमी, जलवायु अस्थिर, और जीवों की जीवनशैली प्रभावित।\",\"हवा से जुड़ी प्राकृतिक घटनाएँ – पवनचक्की, पवन ऊर्जा, ध्वनि, पत्तों का सरसराहट।\",\"हवा की आवश्यकता – मानव शरीर को ठंडक पहुँचाती है, हवा के बिना गर्मी बढ़ती है।\",\"हवा के संरक्षण के उपाय – पेड़ लगाना, हरित क्षेत्र बढ़ाना, प्रदूषण घटाना।\",\"हवा के प्रकार – ताजी हवा, ठंडी हवा, गरम हवा, पवन, वायु प्रवाह।\",\"हवा के प्रभाव – मौसम परिवर्तन, तूफान, बाढ़, सूखा।\",\"हवा के बारे में सीखने के लिए – कविता पाठ, चित्र बनाना, प्रकृति में घूमना।\",\"हवा के साथ खेल – पत्ते उड़ाना, पतंग उड़ाना, हवा के साथ नृत्य।\",\"हवा के बारे में सवाल – ‘हवा क्यों महत्वपूर्ण है?’, ‘हवा के गुण क्या हैं?’\"]','[{\"q\":\"कविता में हवा को किस नाम से बुलाया गया है?\",\"options\":[\"सर्द हवा\",\"बसंती हवा\",\"शीत हवा\",\"गर्मी की हवा\"],\"answer\":1,\"explain\":\"कविता का शीर्षक ‘बसंती हवा’ है, इसलिए हवा को उसी नाम से बुलाया गया है।\"},{\"q\":\"हवा को कविता में कौन-सा शब्द ‘बावली’ के रूप में वर्णित किया गया है?\",\"options\":[\"मस्तमौला\",\"सिरमौर\",\"कुशाग्र\",\"सुरभि\"],\"answer\":0,\"explain\":\"कविता में हवा को ‘बावली’ और ‘मस्तमौला’ कहा गया है।\"},{\"q\":\"हवा के गुणों में से कौन-सा नहीं है?\",\"options\":[\"हल्की\",\"चंचल\",\"भारी\",\"ऊर्जावान\"],\"answer\":2,\"explain\":\"हवा हल्की, चंचल और ऊर्जावान होती है, लेकिन भारी नहीं।\"},{\"q\":\"हवा के संरक्षण के लिए क्या उपाय सुझाए गए हैं?\",\"options\":[\"पेड़ लगाना\",\"धूम्रपान बढ़ाना\",\"कचरा फेंकना\",\"सड़क पर गाड़ी चलाना\"],\"answer\":0,\"explain\":\"पेड़ लगाना हवा के संरक्षण का एक अच्छा उपाय है।\"},{\"q\":\"कविता में हवा को किस प्रकार के शब्द से वर्णित किया गया है?\",\"options\":[\"संगीतमय\",\"गंभीर\",\"संगीन\",\"भारी\"],\"answer\":0,\"explain\":\"हवा को ‘संगीतमय’ और ‘चंचल’ शब्दों से वर्णित किया गया है।\"},{\"q\":\"हवा के बिना प्रकृति में क्या होता है?\",\"options\":[\"पौधे बढ़ते हैं\",\"मौसम स्थिर रहता है\",\"पानी की कमी होती है\",\"पौधे नहीं बढ़ते\"],\"answer\":3,\"explain\":\"हवा के बिना पौधे नहीं बढ़ते और मौसम अस्थिर रहता है।\"},{\"q\":\"हवा के प्रकार में कौन-सा विकल्प सही है?\",\"options\":[\"ताजी हवा\",\"गरम हवा\",\"पवन\",\"ऊपर के सभी\"],\"answer\":3,\"explain\":\"सभी विकल्प हवा के प्रकार हैं।\"},{\"q\":\"कविता में हवा को किस शब्द से ‘बड़ी बावली’ कहा गया है?\",\"options\":[\"मस्तमौला\",\"बावली\",\"सिरमौर\",\"कुशाग्र\"],\"answer\":1,\"explain\":\"हवा को ‘बड़ी बावली’ कहा गया है।\"},{\"q\":\"हवा के संरक्षण के लिए कौन-सा कार्य नहीं किया जाना चाहिए?\",\"options\":[\"पेड़ लगाना\",\"कचरा इकट्ठा करना\",\"धूम्रपान करना\",\"सड़क पर गाड़ी चलाना\"],\"answer\":2,\"explain\":\"धूम्रपान हवा को प्रदूषित करता है, इसलिए इसे नहीं करना चाहिए।\"},{\"q\":\"कविता में हवा के बारे में कौन-सा कथन सही है?\",\"options\":[\"हवा स्थिर रहती है\",\"हवा चलती है\",\"हवा भारी है\",\"हवा नहीं चलती\"],\"answer\":1,\"explain\":\"कविता में हवा को चलती हुई वर्णित किया गया है।\"}]','nvidia/openai/gpt-oss-20b','2026-10-17 16:34:55'),(24956,64,6,'Hindi','hi','उपहार','[\"उपहार का मतलब है किसी को कुछ देना या देना स्वीकार करना।\",\"उपहार देने से मन खुश होता है और रिश्ते मजबूत होते हैं।\",\"उपहार देने के समय सोच-समझकर चुनना चाहिए – प्राप्तकर्ता की पसंद और ज़रूरत को ध्यान में रखें।\",\"उपहार देने के कई कारण हो सकते हैं: जन्मदिन, त्योहार, आभार, बधाई आदि।\",\"उपहार देने से आप अपनी भावनाएँ व्यक्त कर सकते हैं।\",\"उपहार देने के साथ एक छोटा सा संदेश या कार्ड भी जोड़ें।\",\"उपहार देने के बाद धन्यवाद कहना न भूलें।\",\"उपहार देने के समय पैकेजिंग भी महत्