INSERT INTO `ep_questions` VALUES (8800318,901408,'descriptive','3',2,2,'textbook:book','','एक शब्द\nजन्मदिन -प्रेमस्वरूप श्रीवास्तव जन्म : ११ मार्च १९२९, खरौना, जौनपुर (उ.प्र.)','','','श्रीवास्तव','',0,0,0,NULL),(8800319,901408,'descriptive','2',2,2,'textbook:book','','जन्मदिन पर उपहार देना परंपरा नहीं है। (सही / गलत)','','','false','',0,0,0,NULL),(8800320,901409,'descriptive','5',2,2,'textbook:book','','वर्णनात्मक\nसुनो, पढ़ो और गाओ।','','','लोरी गाने के माध्यम से बच्चे को शांति और सुख का अनुभव कराया जाता है।','',0,0,0,NULL),(8800321,901409,'fillinblanks','1',1,2,'textbook:book','','बबलू की आदत से कौन परेशान थे? ______','','','बबलू की आदत से उसके दोस्त परेशान थे।','',0,0,0,NULL),(8800322,901409,'descriptive','4',2,2,'textbook:book','','गणित\nएक से सौ तक की उलटी गिनती पढ़ो और कॉपी में लिखो।','','','100, 99, 98, …, 3, 2, 1','',0,0,0,NULL),(8800323,901409,'descriptive','2',2,2,'textbook:book','','बबलू ने कभी नहीं जाना कि उसकी माँ उसे प्यार करती है। (सही / गलत)','','','false','',0,0,0,NULL),(8800324,901409,'descriptive','2',2,2,'textbook:book','','शीला मौसी ने बिजली की कटौती का कारण बताया कि यह बिजली कंपनी की गलती है। (सही / गलत)','','','false','',0,0,0,NULL),(8800325,901409,'descriptive','2',2,2,'textbook:book','','प्यास के कारण बबलू की स्थिति अच्छी बनी थी। (सही / गलत)','','','false','',0,0,0,NULL),(8800326,901410,'descriptive','5',5,2,'textbook:typed','','पाच ते दहा ओळींचा परिच्छेद लिहा.\nउपयोग शब्द के महत्व पर एक परिच्छेद लिखें।','','','उपयोग शब्द हमारे रोज़मर्रा के संवाद में महत्वपूर्ण भूमिका निभाता है। यह शब्द किसी वस्तु या क्रिया के सामान्य प्रयोग को दर्शाता है, जिससे हमें उसकी उपयोगिता और महत्व समझ में आता है। उदाहरण के लिए, \'उपयोगी उपकरण\' या \'उपयोग का तरीका\' जैसे वाक्य हमें स्पष्ट जानकारी देते हैं। इसके अलावा, उपयोग शब्द का सही प्रयोग हमें गलतफहमी से बचाता है और संवाद को प्रभावी बनाता है।','',0,0,0,NULL),(8800327,901410,'descriptive','5',5,2,'textbook:typed','','पाच ते दहा ओळींचा परिच्छेद लिहा.\nदुरुपयोग शब्द के महत्व पर एक परिच्छेद लिखें।','','','दुरुपयोग शब्द हमें किसी वस्तु या क्रिया के गलत या अनैतिक प्रयोग के प्रति सतर्क करता है। यह शब्द समाज में जिम्मेदारी और नैतिकता के महत्व को रेखांकित करता है। उदाहरण के लिए, दुरुपयोग से पर्यावरण, स्वास्थ्य और सामाजिक व्यवस्था पर नकारात्मक प्रभाव पड़ सकता है। इसलिए, दुरुपयोग शब्द का सही प्रयोग हमें जागरूकता बढ़ाने और सही व्यवहार को प्रोत्साहित करने में मदद करता है।','',0,0,0,NULL),(8800328,901410,'descriptive','4',4,2,'textbook:typed','','चार ते पाच वाक्यांत उत्तर द्या.\nशब्द \'उपयोग\' का अर्थ स्पष्ट करें.','','','उपयोग का अर्थ है किसी वस्तु या क्रिया का सामान्य प्रयोग। यह शब्द रोज़मर्रा के संवाद में किसी चीज़ के उपयोग को दर्शाने के लिए प्रयोग होता है।','',0,0,0,NULL),(8800329,901410,'descriptive','4',4,2,'textbook:typed','','चार ते पाच वाक्यांत उत्तर द्या.\nशब्द \'दुरुपयोग\' का अर्थ स्पष्ट करें.','','','दुरुपयोग का अर्थ है किसी वस्तु या क्रिया का गलत या अनैतिक प्रयोग। यह शब्द समाज में जागरूकता बढ़ाने और गलत व्यवहार को रोकने के लिए प्रयोग होता है।','',0,0,0,NULL),(8800330,901410,'fillinblanks','1',1,2,'textbook:book','','वाक्य में _______ शब्द का प्रयोग करके प्रश्न बनाया जाता है।','','','प्रश्नवाचक','',0,0,0,NULL),(8800331,901410,'fillinblanks','1',1,2,'textbook:typed','','उपयोग हमारे शब्द का अर्थ ________ होता है।','','','सामान्य','',0,0,0,NULL),(8800332,901410,'fillinblanks','1',1,2,'textbook:typed','','वाक्य में \'उपयोग\' शब्द का प्रयोग करते हुए एक उदाहरण वाक्य लिखें: मैं रोज़ ________ का उपयोग करता हूँ।','','','सामान्य','',0,0,0,NULL),(8800333,901410,'fillinblanks','1',1,2,'textbook:typed','','शब्द \'उपयोग\' का विलोम शब्द ________ है।','','','दुरुपयोग','',0,0,0,NULL),(8800334,901410,'fillinblanks','1',1,2,'textbook:typed','','वाक्य में \'उपयोग\' शब्द का प्रयोग करते हुए एक वाक्य लिखें: यह उपकरण ________ के लिए बनाया गया है।','','','उपयोग','',0,0,0,NULL),(8800335,901410,'fillinblanks','1',1,2,'textbook:typed','','शब्द \'उपयोग\' का व्युत्पन्न शब्द ________ है।','','','उपयोगी','',0,0,0,NULL),(8800336,901410,'descriptive','3',2,2,'textbook:typed','','व्याकरण विषयक प्रश्न.\nशब्द \'उपयोग\' का कौन सा व्याकरणिक वर्ग है?','','','संज्ञा','',0,0,0,NULL),(8800337,901410,'descriptive','3',2,2,'textbook:typed','','व्याकरण विषयक प्रश्न.\nशब्द \'उपयोग\' का वचन क्या है?','','','एकवचन','',0,0,0,NULL),(8800338,901410,'descriptive','3',2,2,'textbook:typed','','व्याकरण विषयक प्रश्न.\nशब्द \'उपयोग\' का विभक्ति कौन सी है?','','','कर्म','',0,0,0,NULL),(8800339,901410,'descriptive','2',2,2,'textbook:book','','समानार्थी शब्दों को मिलाएँ।','','','A-C','',0,0,0,NULL),(8800340,901410,'mcq','2',1,2,'textbook:typed','','शब्द \'उपयोग\' का सही अर्थ काय आहे?\nA) सामान्य उपयोग  B) दुरुपयोग  C) उपयोगी','','','सामान्य उपयोग','',0,0,0,NULL),(8800341,901410,'mcq','2',1,2,'textbook:typed','','शब्द \'उपयोग\' का विलोम शब्द काय आहे?\nA) सामान्य उपयोग  B) दुरुपयोग  C) उपयोगी','','','दुरुपयोग','',0,0,0,NULL),(8800342,901410,'mcq','2',1,2,'textbook:typed','','शब्द \'उपयोग\' का व्युत्पन्न शब्द काय आहे?\nA) उपयोगी  B) उपयोगिता  C) उपयोगिता','','','उपयोगी','',0,0,0,NULL),(8800343,901410,'mcq','2',1,2,'textbook:typed','','शब्द \'उपयोग\' का प्रयोग के लिए कौन सा वाक्य उपयुक्त है?\nA) मैं रोज़ उपयोग करता हूँ।  B) मैं रोज़ दुरुपयोग करता हूँ।  C) मैं रोज़ उपयोगी हूँ।','','','मैं रोज़ उपयोग करता हूँ।','',0,0,0,NULL),(8800344,901410,'mcq','2',2,2,'textbook:typed','','निम्नलिखित शब्दों में से कौन सा शब्द अन्य से अलग है?\nA) उपयोग  B) उपयोगी  C) उपयोगिता  D) दुरुपयोग','','','दुरुपयोग - कारण विलोम शब्द है','',0,0,0,NULL),(8800345,901410,'descriptive','3',1,2,'textbook:typed','','एक वाक्यात उत्तर लिहा.\nशब्द \'उपयोग\' का उपयोग किस प्रकार के वाक्य में किया जाता है?','','','सामान्य वाक्य में उपयोग किया जाता है।','',0,0,0,NULL),(8800346,901410,'descriptive','3',1,2,'textbook:typed','','एक वाक्यात उत्तर लिहा.\nशब्द \'उपयोग\' का प्रयोग किस प्रकार के लेखन में होता है?','','','सामान्य लेखन में।','',0,0,0,NULL),(8800347,901410,'descriptive','3',1,2,'textbook:typed','','एक शब्द लिहा.\nशब्द \'उपयोग\' का विलोम शब्द क्या है?','','','दुरुपयोग','',0,0,0,NULL),(8800348,901410,'descriptive','3',1,2,'textbook:typed','','एक शब्द लिहा.\nशब्द \'उपयोग\' का व्युत्पन्न शब्द क्या है?','','','उपयोगी','',0,0,0,NULL),(8800349,901410,'descriptive','3',1,2,'textbook:typed','','एक शब्द लिहा.\nशब्द \'उपयोग\' का अर्थ क्या है?','','','सामान्य','',0,0,0,NULL),(8800350,901410,'descriptive','3',1,2,'textbook:typed','','एक शब्द लिहा.\nशब्द \'उपयोग\' का प्रयोग किस प्रकार के वाक्य में हो सकता है?','','','सामान्य','',0,0,0,NULL),(8800351,901410,'descriptive','3',1,2,'textbook:typed','','एक शब्द लिहा.\nशब्द \'उपयोग\' का लिंग क्या है?','','','पुल्लिंग','',0,0,0,NULL),(8800352,901410,'descriptive','4',4,2,'textbook:typed','','का कारण द्या.\nशब्द \'उपयोग\' का उपयोग क्यों आवश्यक है?','','','उपयोग शब्द से हम किसी वस्तु या क्रिया के सामान्य प्रयोग को स्पष्ट कर सकते हैं, जिससे संवाद स्पष्ट और प्रभावी बनता है।','',0,0,0,NULL),(8800353,901410,'descriptive','4',4,2,'textbook:typed','','का कारण द्या.\nशब्द \'दुरुपयोग\' का प्रयोग क्यों महत्वपूर्ण है?','','','दुरुपयोग शब्द से हम किसी वस्तु या क्रिया के गलत या अनैतिक प्रयोग की चेतावनी दे सकते हैं, जिससे समाज में जागरूकता बढ़ती है।','',0,0,0,NULL),(8800354,901410,'descriptive','4',4,2,'textbook:typed','','का कारण द्या.\nशब्द \'उपयोगी\' का प्रयोग क्यों आवश्यक है?','','','उपयोगी शब्द से हम किसी वस्तु की उपयोगिता को दर्शाते हैं, जिससे उसकी महत्ता और उपयोगिता स्पष्ट होती है।','',0,0,0,NULL),(8800355,901410,'descriptive','4',3,2,'textbook:typed','','दोन ते तीन वाक्यांत उत्तर द्या.\nशब्द \'उपयोग\' का अर्थ और उपयोग क्या है?','','','उपयोग का अर्थ है सामान्य उपयोग। यह शब्द रोज़मर्रा के वाक्यों में प्रयोग होता है।','',0,0,0,NULL),(8800356,901410,'descriptive','4',3,2,'textbook:typed','','दोन ते तीन वाक्यांत उत्तर द्या.\nशब्द \'उपयोग\' का विलोम शब्द क्या है और इसका अर्थ क्या है?','','','दुरुपयोग। इसका अर्थ है गलत या अनैतिक उपयोग।','',0,0,0,NULL),(8800357,901410,'descriptive','4',3,2,'textbook:typed','','दोन ते तीन वाक्यांत उत्तर द्या.\nशब्द \'उपयोग\' का व्युत्पन्न शब्द क्या है और इसका उपयोग कैसे होता है?','','','उपयोगी। यह विशेषण के रूप में प्रयोग होता है, जैसे \'उपयोगी 